WITH flattened AS (SELECT id, service, level, status_code, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, v) SELECT CASE WHEN status_code >= 445 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, service, APPROX_PERCENTILE(status_code, 0.95) AS status_code_p95, SUM(status_code) AS total_status_code, SUM(status_code) FILTER (WHERE level = 'DEBUG') AS debug_total_status_code, GROUPING_ID() AS gid FROM flattened GROUP BY ROLLUP (CASE WHEN status_code >= 445 THEN 'PREMIUM' ELSE 'STANDARD' END, service) ORDER BY total_status_code NULLS LAST;
